import Foundation                                // 실제 의존. 외부 패키지 없음.

// ───────────── 크기 ─────────────

@location('Sources/SlopDisk/SDSize.swift')
imagine struct SDSize: Hashable, Comparable, Sendable, CustomStringConvertible {
    var bytes: UInt64
    static func bytes(_ n: some BinaryInteger) -> SDSize
    static func kilobytes(_ n: some BinaryInteger) -> SDSize      // × 1024
    static func megabytes(_ n: some BinaryInteger) -> SDSize      // × 1024²
    static func gigabytes(_ n: some BinaryInteger) -> SDSize      // × 1024³
    static func terabytes(_ n: some BinaryInteger) -> SDSize      // × 1024⁴

    requirements(`
        이진 단위만 쓴다 (D3). 음수와 UInt64 오버플로는 precondition 실패로 처리한다.
        description은 값이 1 이상이 되는 가장 큰 단위(B, KiB, MiB, GiB, TiB)로 쓰고,
        소수점 이하는 최대 2자리까지만 보이며 끝의 0과 점은 지운다.
    `);
    ensure(SDSize.megabytes(400).bytes == 419_430_400);
    ensure(SDSize.megabytes(400).description == "400 MiB");
    ensure(SDSize.megabytes(8192).description == "8 GiB");
    ensure(SDSize.bytes(512).description == "512 B");
    ensure(SDSize.bytes(1536).description == "1.5 KiB");
}

@location('Sources/SlopDisk/SDSize.swift')
imagine enum SDPartitionExtent: Hashable, Sendable {
    case size(SDSize)
    case remaining                                   // P1
    // hint: `.megabytes(400)`을 이 타입 문맥에서도 쓸 수 있게 SDSize와 같은 이름의 static 팩토리 5개를 둔다.
}

// ───────────── 에러 ─────────────

@location('Sources/SlopDisk/SDError.swift')
enum SDError: Error, Hashable, Sendable {
    // hint: 케이스 이름은 계약이다. 연관값의 세부 모양은 실행자가 정한다.
    case io(operation: String, errno: Int32)
    case device(description: String)                 // 외부 SDBlockDevice 구현체용 (D28)
    case invalidArgument(String)
    case fileExists(path: String)                    // D15
    case locked(path: String)                        // D26
    case readOnly
    case diskTooSmall(minimum: SDSize)               // D25
    case gptUnrecoverable                            // D13
    case schemeNotGPT                                // D12
    case transactionFinished                         // D8
    case transactionInProgress                       // §5 재진입
    case labelTooLong(utf16Count: Int)               // D17
    case invalidPartitionType                        // 전부 0인 GUID
    case insufficientSpace(requested: SDSize)
    case outOfUsableRange
    case overlapsExistingPartition(SDPartition.ID)
    case tooManyPartitions                           // P4
    case partitionNotFound(SDPartition.ID)
    case duplicateUniqueID(UUID)
    case verificationFailed(String)                  // D11
}

// ───────────── 블록 디바이스 ─────────────

@location('Sources/SlopDisk/SDBlockDevice.swift')
public protocol SDBlockDevice: AnyObject {
    var sectorSize: Int { get }                      // 512 또는 4096
    var sectorCount: UInt64 { get }
    var isReadOnly: Bool { get }
    func read(lba: UInt64, into buffer: UnsafeMutableRawBufferPointer) throws(SDError)
    func write(lba: UInt64, from buffer: UnsafeRawBufferPointer) throws(SDError)
    func synchronize() throws(SDError)
    // hint: buffer.count는 sectorSize의 배수여야 하고 lba + buffer.count / sectorSize <= sectorCount여야 한다.
    //       위반하면 .invalidArgument. isReadOnly인데 write를 부르면 .readOnly.
}
public enum SDOpenMode: Sendable { case readOnly, readWrite }

@location('Sources/SlopDisk/Devices/SDMemoryBlockDevice.swift')
imagine final class SDMemoryBlockDevice: SDBlockDevice {
    init(sectorSize: Int, sectorCount: UInt64)
    var allocatedByteCount: Int { get }
    func bytes(atByteOffset offset: UInt64, count: Int) -> [UInt8]
    func export(toFile path: String) throws(SDError)

    requirements(`
        64 KiB 청크 단위의 희소 저장소다 (D24). 쓴 적 없는 청크는 할당하지 않고 읽으면 0이 나온다.
        synchronize()는 아무것도 하지 않는다. isReadOnly는 항상 false다.
        export는 할당된 청크만 pwrite하고 ftruncate로 전체 크기를 맞춘 희소 파일을 만든다.
        대상 파일이 이미 있으면 .fileExists.
    `);
    ensure(`8 TiB(섹터 512) 디바이스를 만든 직후 allocatedByteCount == 0`);
    ensure(`LBA 0에 한 섹터를 쓰면 allocatedByteCount == 65536`);
    ensure(`쓰지 않은 임의의 LBA를 읽으면 전부 0`);
    ensure(`export한 파일을 SDFileBlockDevice로 열어 읽은 바이트 == 원본 bytes(atByteOffset:count:)`);
}

@location('Sources/SlopDisk/Devices/SDFileBlockDevice.swift')
imagine final class SDFileBlockDevice: SDBlockDevice {
    static func create(path: String, byteCount: UInt64, sectorSize: Int) throws(SDError) -> SDFileBlockDevice
    init(path: String, mode: SDOpenMode, sectorSize: Int) throws(SDError)
    let path: String

    requirements(`
        create는 open(O_RDWR|O_CREAT|O_EXCL, 0644)로 연다. EEXIST면 .fileExists (D15).
          크기는 ftruncate로 잡아 희소 파일이 되게 한다. create로 연 디바이스는 readWrite다.
        init은 기존 파일을 연다. sectorCount = 파일 크기 / sectorSize이고 남는 바이트는 무시한다.
        flock은 readWrite면 LOCK_EX|LOCK_NB, readOnly면 LOCK_SH|LOCK_NB로 건다.
          EWOULDBLOCK이면 .locked(path:) (D26).
        read/write는 pread/pwrite를 루프로 돌린다. 짧은 I/O와 EINTR을 처리한다.
        synchronize는 Darwin이면 fcntl(F_FULLFSYNC)을 쓰고, 실패하면 fsync로 폴백한다. Linux는 fsync다.
        deinit에서 close한다(잠금도 함께 풀린다).
    `);
    ensure(`같은 경로를 readWrite로 두 번 열면 두 번째가 .locked`);
    ensure(`같은 경로를 readOnly로 두 번 열면 둘 다 성공`);
    ensure(`readOnly로 열린 동안 readWrite 열기는 .locked`);
    ensure(`create 대상이 이미 있으면 .fileExists를 던지고 기존 파일 내용은 그대로`);
}

// ───────────── 모델 ─────────────

@location('Sources/SlopDisk/Model/')
imagine struct SDPartitionType: Hashable, Sendable, CustomStringConvertible {
    var guid: UUID
    init(guid: UUID)
    var name: String?                                // 아는 타입이면 사람이 읽을 이름
    static let efiSystem          // C12A7328-F81F-11D2-BA4B-00A0C93EC93B  "EFI System"
    static let microsoftBasicData // EBD0A0A2-B9E5-4433-87C0-68B6B72699C7  "Microsoft Basic Data"
    static let microsoftReserved  // E3C9E316-0B5C-4DB8-817D-F92DF00215AE  "Microsoft Reserved"
    static let microsoftRecovery  // DE94BBA4-06D1-4D40-A16A-BFD50179D6AC  "Windows Recovery"
    static let biosBoot           // 21686148-6449-6E6F-744E-656564454649  "BIOS Boot"
    static let linuxFilesystem    // 0FC63DAF-8483-4772-8E79-3D69D8477DE4  "Linux Filesystem"
    static let linuxSwap          // 0657FD6D-A4AB-43C4-84E5-0933C84B4F4F  "Linux Swap"
    static let appleAPFS          // 7C3457EF-0000-11AA-AA11-00306543ECAC  "Apple APFS"
    static let appleHFSPlus       // 48465300-0000-11AA-AA11-00306543ECAC  "Apple HFS+"
    requirements(`
        모르는 GUID도 그대로 보존한다. description은 name이 있으면 name, 없으면 GUID 대문자 문자열이다.
        .fat32는 만들지 않는다 (D7).
    `);
}

imagine struct SDPartitionAttributes: OptionSet, Hashable, Sendable {
    var rawValue: UInt64
    static let requiredPartition   // bit 0
    static let noBlockIOProtocol   // bit 1
    static let legacyBIOSBootable  // bit 2
    static let msReadOnly          // bit 60 (Microsoft Basic Data 전용)
    static let msShadowCopy        // bit 61
    static let msHidden            // bit 62
    static let msNoDriveLetter     // bit 63
    requirements(`모르는 비트도 읽고 쓸 때 그대로 보존한다.`);
}

imagine struct SDPartition: Identifiable, Hashable, Sendable {
    var id: UUID { uniqueID }
    let index: Int                                   // 엔트리 슬롯 (0부터)
    let type: SDPartitionType
    let uniqueID: UUID
    let begin: UInt64                                // first LBA
    let end: UInt64                                  // last LBA, 포함 (D16)
    let attributes: SDPartitionAttributes
    let label: String
    let sectorSize: Int
    var size: SDSize                                 // (end - begin + 1) * sectorSize
    var lbaRange: ClosedRange
    var byteOffset: UInt64                           // begin * sectorSize
}

imagine enum SDPartitionScheme: Hashable, Sendable {
    case none                                        // GPT 증거도, 유효한 MBR도 없음
    case gpt(SDGPTHealth)
    case mbr([SDMBRPartition])                       // 보호 MBR이 아닌 실제 MBR. 읽기 전용 보고
}

imagine enum SDGPTHealth: Hashable, Sendable {
    case healthy
    case degraded(Set)
}

imagine enum SDGPTIssue: Hashable, Sendable {
    case primaryHeaderInvalid(SDGPTHeaderDamage)
    case primaryEntriesCRCMismatch
    case backupHeaderInvalid(SDGPTHeaderDamage)
    case backupEntriesCRCMismatch
    case backupNotAtEndOfDisk                        // AlternateLBA != 마지막 LBA (이미지를 늘린 경우)
    case protectiveMBRMissing                        // GPT는 유효하나 LBA0에 0xEE가 없음
    case hybridMBR                                   // 0xEE 외 MBR 엔트리 존재. commit/repair 시 사라짐
    case copiesDiffer                                // P10
    case invalidEntries                              // CRC는 맞으나 겹침·범위 밖 엔트리
}
imagine enum SDGPTHeaderDamage: Hashable, Sendable { case signature, headerCRC, fields }

imagine struct SDMBRPartition: Hashable, Sendable {
    let index: Int                                   // 0..<4
    let isBootable: Bool
    let type: UInt8
    let firstLBA: UInt32
    let sectorCount: UInt32
}

// ───────────── 읽기 (P6) ─────────────

@location('Sources/SlopDisk/SDInspection.swift')
imagine struct SDInspection: Sendable {
    static func read(from device: any SDBlockDevice) throws(SDError) -> SDInspection
    let sectorSize: Int
    let sectorCount: UInt64
    let mbr: MBRReport                               // 시그니처, 원시 엔트리 4개, 보호/하이브리드/일반 판정
    let primary: HeaderReport?                       // LBA1. 시그니처가 없으면 nil
    let backup: HeaderReport?                        // 주의 AlternateLBA, 없으면 마지막 LBA
    let scheme: Result   // 판정 결과. 양쪽 손상이면 .failure(.gptUnrecoverable)
    let diskID: UUID?
    let partitions: [SDPartition]                    // 채택된 사본 기준

    imagine struct HeaderReport: Sendable {
        let lba: UInt64
        let damage: SDGPTHeaderDamage?               // nil이면 헤더 유효
        let storedHeaderCRC: UInt32, computedHeaderCRC: UInt32
        let storedEntriesCRC: UInt32, computedEntriesCRC: UInt32?
        // + 헤더 필드 전부 (MyLBA, AlternateLBA, FirstUsable, LastUsable, DiskGUID, EntryLBA, 개수, 크기)
    }
    requirements(`
        손상이 있어도 throw하지 않고 I/O 오류에서만 throw한다. 판정 알고리즘은 §4를 따른다.
        sdinspect가 이 구조체 하나로 모든 출력을 만들 수 있어야 한다.
    `);
}

// ───────────── 디스크 ─────────────

@location('Sources/SlopDisk/SDDisk.swift')
imagine final class SDDisk {
    init(device: any SDBlockDevice, ignoringExistingTable: Bool = false) throws(SDError)
    let device: any SDBlockDevice
    var sectorSize: Int { get }
    var sectorCount: UInt64 { get }
    var size: SDSize { get }
    private(set) var scheme: SDPartitionScheme
    private(set) var partitions: [SDPartition]      // P2
    private(set) var diskID: UUID?                  // GPT일 때만
    func refresh() throws(SDError)
    func repair() throws(SDError)
    func withTransaction(_ body: (inout SDTransaction) throws -> R) throws -> R

    requirements(`§4, §5, §7을 따른다. non-Sendable이다 (D14).`);
    ensure(`F4 fixture를 열면 scheme == .gpt(.healthy), partitions.count == 1, begin 40, end 16343, label "disk image"`);
    ensure(`주 헤더의 바이트 오프셋 512 + 40(FirstUsableLBA)을 1 증가시킨 뒤 열면 .gpt(.degraded(primaryHeaderInvalid(.headerCRC)을 포함)), partitions는 동일, 디바이스 바이트는 불변`);
    ensure(`그 상태에서 repair() 후 refresh()하면 .gpt(.healthy)`);
    ensure(`주·백업 헤더를 모두 훼손하면 init이 .gptUnrecoverable을 던지고, ignoringExistingTable: true로는 scheme == .none으로 열림`);
}

@location('Sources/SlopDisk/SDTransaction.swift')
imagine struct SDTransaction: ~Copyable {
    var partitions: [SDPartition] { get }           // 스테이징 상태, P2
    mutating func clear(diskID: UUID? = nil)
    @discardableResult
    mutating func addPartition(_ extent: SDPartitionExtent,
                               type: SDPartitionType,
                               label: String = "",
                               attributes: SDPartitionAttributes = [],
                               at startLBA: UInt64? = nil,
                               uniqueID: UUID? = nil) throws(SDError) -> SDPartition
    mutating func removePartition(_ id: SDPartition.ID) throws(SDError)
    mutating func setLabel(_ label: String, of id: SDPartition.ID) throws(SDError)
    mutating func setType(_ type: SDPartitionType, of id: SDPartition.ID) throws(SDError)
    mutating func setAttributes(_ attributes: SDPartitionAttributes, of id: SDPartition.ID) throws(SDError)
    @discardableResult
    mutating func resizePartition(_ id: SDPartition.ID, to extent: SDPartitionExtent) throws(SDError) -> SDPartition
    mutating func commit() throws(SDError)

    requirements(`§6, §7을 따른다.`);
    ensure(`빈 16 GiB(512) 디스크에서 clear 후 .megabytes(400) EFI → begin 2048, end 821247`);
    ensure(`이어서 .megabytes(8192) → begin 821248, end 17598463, size.description == "8 GiB"`);
    ensure(`64 MiB(512) 디스크에서 clear 후 .megabytes(16) EFI, .remaining → 두 번째는 begin 34816, end 131038`);
    ensure(`64 MiB(4096) 디스크에서 같은 조작 → 첫 번째 begin 256, 두 번째 end == sectorCount - 1 - 1 - 4`);
    ensure(`레이블 "윈도우설치" (5유닛)는 통과, "💾" × 18 (36유닛)은 통과, "💾" × 19 (38유닛)은 .labelTooLong`);
    ensure(`commit 없이 클로저가 끝나면 디바이스 바이트 불변, disk.partitions 불변`);
    ensure(`commit 후 addPartition → .transactionFinished`);
    ensure(`.mbr 또는 .none 디스크에서 clear 없이 addPartition → .schemeNotGPT`);
}

// ───────────── 팩토리 ─────────────

@location('Sources/SlopDisk/SDDiskImage.swift')
public enum SDDiskImageSource: Sendable {
    case file(String)                                // D18
    case inMemory                                    // D24
}

@location('Sources/SlopDisk/SDDiskImage.swift')
imagine enum SDDiskImage {
    static func create(_ source: SDDiskImageSource, desiredSize: SDSize, sectorSize: Int = 512) throws(SDError) -> SDDisk
    static func open(_ source: SDDiskImageSource, mode: SDOpenMode = .readWrite, sectorSize: Int? = nil) throws(SDError) -> SDDisk
    requirements(`§8을 따른다.`);
    ensure(`create(.inMemory, desiredSize: .bytes(1_048_577)) → size.bytes == 1_049_088 (섹터 512 배수로 올림)`);
    ensure(`create(.inMemory, desiredSize: .bytes(512 * 67)) → .diskTooSmall`);
    ensure(`create 직후 scheme == .none, partitions.isEmpty`);
    ensure(`open(.inMemory) → .invalidArgument`);
    ensure(`4096 섹터로 만든 파일 이미지를 sectorSize: nil로 open → sectorSize == 4096`);
}

import Foundation
import SlopDisk

let disk = try SDDiskImage.create(.inMemory, desiredSize: .gigabytes(16))
// let disk = try SDDiskImage.open(.file("/tmp/disk-image.img"))
// try disk.refresh()

if disk.partitions.isEmpty {
    print("== NO PARTITIONS ==")
} else {
    for partition in disk.partitions {
        print("Partition #\(partition.index): \(partition.begin) ~ \(partition.end) (\(partition.size))")
    }
}

try disk.withTransaction { txn in
    txn.clear()

    try txn.addPartition(.megabytes(400), type: .efiSystem, label: "EFI")
    try txn.addPartition(.megabytes(8192), type: .microsoftBasicData, label: "WIN11ISO")
    // writes partition table and sync()
    try txn.commit()
}
